--- src/StyleGuide.module.css ---
.guide{max-width:70rem;margin:0 auto;padding:var(--space-4);}
.panel,.stat{margin-block:var(--space-4);padding:var(--space-4);background:var(--surface);color:var(--text);border:1px solid var(--border);border-radius:var(--radius);}
.header,.examples{display:flex;align-items:center;justify-content:space-between;gap:var(--space-2);flex-wrap:wrap;}
.button{padding:var(--space-2) var(--space-4);border:1px solid currentColor;border-radius:var(--radius);cursor:pointer;}
.primary{background:var(--color-primary);color:var(--bg);}
.secondary{background:var(--surface);color:var(--text);}
.danger{color:var(--color-danger);}
.button.danger{background:var(--color-danger);color:var(--bg);}
.button:disabled,.input:disabled{opacity:0.5;cursor:not-allowed;}
.button:focus-visible,.input:focus-visible{outline:2px solid var(--color-primary);outline-offset:2px;}
.badge{display:inline-block;padding:var(--space-1) var(--space-2);margin:var(--space-1);border:1px solid currentColor;border-radius:var(--radius);}
.neutral{color:var(--text-muted);}.success{color:var(--color-success);}.warning{color:var(--color-warning);}
.highlight{outline:2px solid var(--color-danger);}.muted{color:var(--text-muted);}
.swatches{list-style:none;padding:0;display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,16rem),1fr));gap:var(--space-2);}
.swatches li{display:flex;align-items:center;gap:var(--space-2);flex-wrap:wrap;}.swatch{display:inline-block;width:2rem;height:2rem;border:1px solid var(--border);border-radius:var(--radius);}
.field{display:grid;gap:var(--space-1);margin-block:var(--space-4);}.input{padding:var(--space-2);background:var(--bg);color:var(--text);border:1px solid var(--border);border-radius:var(--radius);}.invalid{border-color:var(--color-danger);}.error{margin:0;color:var(--color-danger);font-size:var(--font-sm);}

